{
  "vulnerable": true,
  "findings": [
    {
      "category": "C1",
      "title": "SOQL Injection in Account Search",
      "severity": "High",
      "file": "AccountSearchController.cls",
      "lines": "4-6",
      "explanation": "The method concatenates the user‑supplied searchKey directly into a dynamic SOQL string without escaping or binding, allowing an attacker to inject arbitrary SOQL clauses and read data beyond their permissions.",
      "remediation": "Use a bind variable or escape the input: `String query = 'SELECT Id, Name, Industry FROM Account WHERE Name LIKE :searchKey LIMIT 50';` or `String query = 'SELECT Id, Name, Industry FROM Account WHERE Name LIKE \'%' + String.escapeSingleQuotes(searchKey) + '%\' LIMIT 50';` and keep USER_MODE for FLS enforcement."
    }
  ]
}

{
  "vulnerable": true,
  "findings": [
    {
      "category": "C2",
      "title": "CRUD/FLS Violation in ContactPhoneService",
      "severity": "Medium",
      "file": "ContactPhoneService.cls",
      "lines": "1-10",
      "explanation": "The method queries and updates Contact records without enforcing field‑level security. It reads the Birthdate field and writes to Phone regardless of the caller’s field permissions, allowing users to see or modify data they should not access.",
      "remediation": "Add WITH SECURITY_ENFORCED to the SOQL query or use Security.stripInaccessible to filter fields. Before updating, check that the user has edit permission on the Phone field (e.g., using Schema.sObjectType.Contact.fields.Phone.isAccessible())."
    }
  ]
}

{
  "vulnerable": true,
  "findings": [
    {
      "category": "C3",
      "title": "Record-level sharing bypass in Aura-enabled class",
      "severity": "Medium",
      "file": "CaseHistoryController.cls",
      "lines": "1-10",
      "explanation": "The class is declared \"without sharing\" and contains an @AuraEnabled method that returns Case records. Without sharing, record-level sharing rules are ignored, allowing any user with the permission set to view cases they should not have access to.",
      "remediation": "Declare the class with \"with sharing\" or \"inherited sharing\", or enforce sharing in the query using WITH USER_MODE or a sharing query. This ensures record-level access is respected for all callers."
    }
  ]
}

{
  "vulnerable": true,
  "findings": [
    {
      "category": "C4",
      "title": "Excessive permissions in Support Agent Tools permission set",
      "severity": "High",
      "file": "Support_Agent_Tools.permissionset-meta.xml",
      "lines": "userPermissions",
      "explanation": "The permission set grants ModifyAllData, ViewAllData, and AuthorApex, which give users full access to all data and the ability to author Apex. This far exceeds the described purpose of only viewing and closing cases, creating a privilege escalation risk for internal users.",
      "remediation": "Remove the ModifyAllData, ViewAllData, and AuthorApex permissions from the permission set. Grant only the necessary Case object permissions (Read, Edit, and Delete if needed) and the ApiEnabled permission if required for API access."
    }
  ]
}
